//check if OPEN disputes other than the one being deleted/edited exist, where the accused is the same as the accused from the deleted/edited dispute

$dispwrp = entity_metadata_wrapper('node', $affected_dispute);

if($dispwrp->field_accused->getIdentifier()) {
	$accused_id = $dispwrp->field_accused->uid->value();

	$sql="SELECT COUNT(node.nid) AS cnt
	FROM {node} node
	INNER JOIN {field_data_field_dispute_status} s ON node.nid = s.entity_id 
	AND s.entity_type = 'node' 
	AND s.deleted = '0'
	LEFT JOIN {field_data_field_accused} a ON node.nid = a.entity_id
	AND a.entity_type = 'node'
	AND a.deleted = '0'
	WHERE node.nid != :exnode
	AND node.status = '1'
	AND node.type = 'dispute'
	AND s.field_dispute_status_value = '0'
	AND a.field_accused_target_id = :acc";

	$result = db_query($sql, array(':acc' => $accused_id,':exnode' => $affected_dispute->nid));
	$resarray = $result->fetchAll();
	$cnt = $resarray[0]->cnt;
	return ($cnt == 0) ? 1 : 0;
}
else
	return false;
